using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace Pengin1011Generator.Localization;

[Generator]
public sealed class LocalizationGenerator : IIncrementalGenerator {
	public void Initialize(IncrementalGeneratorInitializationContext context) {
		context.RegisterPostInitializationOutput(static ctx => ctx.AddSource("Loc.g.cs", SourceText.From(LocSource, new UTF8Encoding(false))));
	}

	private const string LocSource = """
// <auto-generated/>
#nullable enable
namespace Pengin1011.Core;

internal static class Loc {
	public static string Get(string key, global::System.Globalization.CultureInfo? culture = null)
		=> global::Pengin1011.Core.Localization.Localizer.Get(typeof(Loc).Assembly, key, culture);

	public static string Format(string key, params object?[] args)
		=> global::Pengin1011.Core.Localization.Localizer.Format(typeof(Loc).Assembly, key, args);

	public static string Format(global::System.Globalization.CultureInfo culture, string key, params object?[] args)
		=> global::Pengin1011.Core.Localization.Localizer.Format(typeof(Loc).Assembly, culture, key, args);
}
""";
}
